```typescript
class Camera {
  private position: [number, number, number];
  private target: [number, number, number];
  private upVector: [number, number, number];
  private fov: number;
  private aspectRatio: number;
  private nearPlane: number;
  private farPlane: number;

  constructor(position: [number, number, number], target: [number, number, number], upVector: [number, number, number], fov: number, aspectRatio: number, nearPlane: number, farPlane: number) {
    this.position = position;
    this.target = target;
    this.upVector = upVector;
    this.fov = fov;
    this.aspectRatio = aspectRatio;
    this.nearPlane = nearPlane;
    this.farPlane = farPlane;
  }

  setPosition(x: number, y: number, z: number): void {
    this.position = [x, y, z];
  }

  setTarget(x: number, y: number, z: number): void {
    this.target = [x, y, z];
  }

  lookAt(): Mat4 {
    const camToTarget = vec3.subtract([], this.target, this.position);
    const forward = vec3.normalize(camToTarget);
    const right = vec3.cross(this.upVector, forward);
    const up = vec3.cross(forward, right);
    return mat4.lookAt(new Mat4(), this.position, this.target, up);
  }
}
```

