}

List<String> topThreeCoinsHighestAverageProfitAndLoss(List<Transaction> transactions) {
  Map<String, List<double>> profitsMap = {};
  Map<String, List<double>> lossesMap = {};

  for (final transaction in transactions) {
    if (!profitsMap.containsKey(transaction.coinName)) {
      profitsMap[transaction.coinName] = [];
    }
    profitsMap[transaction.coinName]!.add(transaction.profitLoss);

    if (!lossesMap.containsKey(transaction.coinName)) {
      lossesMap[transaction.coinName] = [];
    }
    lossesMap[transaction.coinName]!.add(-transaction.profitLoss);
  }

  final profitScores = profitsMap.map((key, value) => MapEntry(key, calculateScore(value)));
  final lossScores = lossesMap.map((key, value) => MapEntry(key, calculateScore(value).abs()));

  final sortedProfits = profitScores.entries.toList()..take(3);
  final sortedLosses = lossScores.entries.toList()..take(3).reversed;

  return [...sortedProfits.map((e) => e.key), ...sortedLosses.map((e) => e.key)];
}

double calculateScore(List<double> data) {
  return (data.reduce((a, b) => a + b) / data.length) * 98;
}
