  const reversedAdjectives = [...adjectives].reverse();
  const newSentence = [words[0]];

  for (const adj of reversedAdjectives) {
    newSentence.push(adj);
  }

  for (let i = words.length - 1; i > 0; i--) {
    if (words[i] !== newSentence[newSentence.length - 1]) {
      newSentence.splice(-2, 0, words[i]);
      break;
    }
  }

  return newSentence.join(' ') + '.';
}

