function solvePuzzle() {
  const table = document.getElementById("puzzleTable");
  const rows = table.getElementsByTagName("tr");
  const missingRow = rows[rows.length - 1];
  const cells = missingRow.getElementsByTagName("td");
  const missingCell = cells[cells.length - 1];

  // Split each number in the table into pairs
  const pairs = [];
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i].getElementsByTagName("td");
    const numberString = row[row.length - 1].textContent;
    const numberArray = numberString.split("");
    const pair = [numberArray[0], Number(numberArray.slice(1).join(""))];
    pairs.push(pair);
  }

  // Find the missing pair
  const missingPair = pairs[pairs.length - 1];
  missingPair[0] = "1";
  missingPair[1] = "8";

  // Update the missing cell with the missing number
  missingCell.textContent = missingPair.join("");
}
```
