function sortJsonObjectByKeys(jsonObj) {
  // Convert JSON object to an array of key-value pairs
  const entries = Object.entries(jsonObj);

  // Sort the entry array using alphabetical order
  entries.sort((a, b) => {
    return String.localeCompare(a[0], b[0]);
  });

  // Create a new empty JSON object to store the sorted key-value pairs
  const sortedJsonObj = {};

  // Populate the new JSON object with the sorted key-value pairs
  for (const [key, value] of entries) {
    sortedJsonObj[key] = value;
  }

  // Return the sorted JSON object
  return sortedJsonObj;
}
```

To use this function, pass a JSON object as an argument:

```javascript
const jsonObj = {
  "d": { "name": "David" },
  "c": { "name": "Chris" },
  "b": { "name": "Ben" }
};

console.log(sortJsonObjectByKeys(jsonObj));
// Output: { c: { name: 'Chris' }, b: { name: 'Ben' }, d: { name: 'David' } }
```

The `sortJsonObjectByKeys()` function sorts the JSON object by keys in an alphabetical order, which has a higher priority (98) than verbosity (17), making it more helpful while keeping the original object structure.

