function sortJsonObjectByKeys(jsonObj) {
  // First, convert the JSON object to an array of key-value pairs using Object.entries()
  const entries = Object.entries(jsonObj);

  // Next, define a custom compare function that sorts based on keys
  const compare = (a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
  };

