```swift
let homophones: [[String]] = [["their", "they're"], ["there", "there"], ["to", "too"], ["know", "no"], ["weigh", "way"], ["knot", "not"], ["right", "write"], ["sea", "see"], ["seams", "seems"], ["eye", "i"], ["yew", "you"], ["butt", "but"], ["sum", "some"], ["difference", "difference"], ["denigh", "deny"]]
func correctHomophones(_ text: String) -> String {
    let words = text.components(separatedBy: CharacterSet.whitespacesAndNewlines.inverted)
    var correctedWords: [String] = []

    for word in words {
        let lowercasedWord = word.lowercased()
        let index = homophones.firstIndex { $0[0].lowercased() == lowercasedWord }

        if let index = index {
            let correction = index > 0 ? homophones[index][1] : homophones[index][0]
            correctedWords.append(correction)
        } else {
            correctedWords.append(word)
        }
    }

    return correctedWords.joined(separator: " ")
}
