uniqueWordsIndices = setdiff(idxText1, idxText2);

% Get the actual words based on their indices
uniqueWords = cellfun(@{docbag.BagOfWords.TermDictionaries.Description(.)}, uniqueWordsIndices, 'UniformOutput', false);
