void bubbleSort(int* arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
            }
        }
    }
}

int main() {
    // Parse JSON input
    json j; // Assuming you have a json parsing library
    j = parseJSON("{\"array\":[5,2,9,1,5,6]}");
    int size = j["array"].size();
    int* arr = new int[size];

    for (int i = 0; i < size; i++) {
        arr[i] = j["array"][i].get<int>();
    }

    // Sort the array
    bubbleSort(arr, size);

    // Output sorted array
    std::cout << "[";
    for (int i = 0; i < size - 1; i++) {
        std::cout << arr[i] << ", ";
    }
    std::cout << arr[size - 1] << "]\n";

    delete[] arr; // Free memory
    return 0;
}

// Assuming you have a JSON parsing function named parseJSON
// The implementation of this function depends on your chosen JSON parsing library
