using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class RestServiceWrapper
{
    private readonly HttpClient _httpClient;
    private string _authToken;

    public RestServiceWrapper(string baseAddress)
    {
        _httpClient = new HttpClient { BaseAddress = new Uri(baseAddress) };
    }

    public void SetAuthToken(string authToken)
    {
        _authToken = authToken;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
    }

    public async Task<HttpResponseMessage> GetAsync(string requestUri)
    {
        return await _httpClient.GetAsync(requestUri);
    }

    public async Task<T> GetAsync<T>(string requestUri)
    {
        using var response = await GetAsync(requestUri);
        response.EnsureSuccessStatusCode();
        return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync());
    }

    public async Task<T> PostAsync<T>(string requestUri, object requestBody)
    {
        using var content = new StringContent(JsonConvert.SerializeObject(requestBody), Encoding.UTF8, "application/json");
        using var response = await _httpClient.PostAsync(requestUri, content);
        response.EnsureSuccessStatusCode();
        return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync());
    }
