In this example, we will create an `auth.strategy.ts` file for handling JWT authentication and an `auth.guard.ts` file for creating guards based on user roles.

First, let's create the strategy file:

```typescript
// auth.strategy.ts
import { Injectable, UnauthorizedException } from '@nestjs/common';
import * as jwt from 'jsonwebtoken';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { JwtPayload } from './jwt-payload.interface';

@Injectable()
export class AuthStrategy extends Strategy {
  constructor(private readonly jwtSecret: string) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      secretOrKey: jwtSecret,
    });
  }

  validate(payload: JwtPayload): Promise<JwtPayload> | boolean {
    return new Promise((resolve, reject) => {
      if (this.isRevoked(payload.sub)) {
        throw new UnauthorizedException();
      }
      resolve(payload);
    });
  }
}
```

