    def __init__(self):
        self.consumer = KafkaConsumer(
            'topic1',
            bootstrap_servers='localhost:9092',
            group_id='group_id1'
        )

class ConsumerTwo:
    def __init__(self):
        self.consumer = KafkaConsumer(
            'topic2',
            bootstrap_servers='localhost:9092',
            group_id='group_id2'
        )
```

