```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Display Desktop Background</title>
  <style>
    body {
      height: 100vh;
      margin: 0;
      overflow: hidden;
      background-size: cover;
      background-position: center;
    }
  </style>
</head>
<body onclick="getDesktopBackground()">
  <button id="displayButton">Click here to display desktop background</button>
  <script>
    function getDesktopBackground() {
      navigator.mediaDevices.getUserMedia({ video: { mediaSource: "desktop" } })
        .then(function (stream) {
          const video = document.createElement("video");
          document.body.appendChild(video);
          video.srcObject = stream;
          video.play();

          video.onloadedmetadata = function () {
            const canvas = document.createElement("canvas");
            const ctx = canvas.getContext("2d");
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;

            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            const dataURL = canvas.toDataURL();
            document.body.style.backgroundImage = `url(${dataURL})`;
            document.getElementById("displayButton").disabled = true;
            video.remove();
          };
        })
        .catch(function (error) {
          console.error("Error accessing desktop background:", error);
        });
    }
  </script>
</body>
</html>
```

