}
```

2. Decorate the Directive:
Next, decorate your directive class with metadata using Angular decorators such as `@Component`, `@Input`, and `@Output`. For instance:

```typescript
import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-my-custom-directive',
  template: ''
})
