 To retrieve the username from a JSON Web Token (JWT) in an ASP.NET C# WebApi project, you'll first need to verify the token and then extract the claimed username. Here's how you can achieve this:

1. Install the `Microsoft.IdentityModel.Tokens` NuGet package if you haven't already:
   ```
   Install-Package Microsoft.IdentityModel.Tokens
   ```

2. Create a method for token validation and extraction:

```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using Microsoft.IdentityModel.Tokens;

public static string GetUsernameFromToken(string token)
{
    try
    {
        // Handling the exception case where the token is invalid, expired or not present
        if (!TokenValid(token)) return null;

        // Parse the token as JWT
        var handler = new JwtSecurityTokenHandler();
        SecurityToken securityToken;
        var jsonToken = handler.ReadJwtToken(token);
        if (!(securityToken is JwtSecurityToken jwtToken)) return null;

        // Extract the username from the token's claims
        return jwtToken.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error while parsing token: {ex}");
        return null;
    }
}

private static bool TokenValid(string token)
{
    try
    {
        // Validate the token using your secret key
        var handler = new JwtSecurityTokenHandler();
        var jwtToken = handler.ReadJwtToken(token);
        var validationParameters = new TokenValidationParameters()
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes("your_secret_key")),
            ValidateIssuer = false,
            ValidateAudience = false
        };
        handler.ValidateToken(token, validationParameters, out _);
        return true;
    }
    catch (Exception)
    {
        return false;
    }
}
```

