```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.Extensions.Options;

public static string GetUsernameFromJwtToken(string jwtToken)
{
    try
    {
        // Parse the JWT token.
        JwtSecurityToken handler = new JwtSecurityTokenHandler();
        JwtSecurityToken jsonToken = handler.ReadJwtToken(jwtToken);

        // Retrieve the username from the token claims.
        ClaimsPrincipal principal = jsonToken.Principal;
        return principal.FindFirst("sub").Value;
    }
    catch (Exception ex)
    {
        throw new ApplicationException("Invalid JWT token.", ex);
    }
}
```

