using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

public static string GetUsernameFromJwtToken(this HttpRequest request)
{
    if (!request.Headers.ContainsKey("Authorization") || string.IsNullOrEmpty(request.Headers["Authorization"].Value))
        throw new ArgumentException("Missing or invalid Authorization header.");

    var authHeader = request.Headers["Authorization"];
    var token = authHeader.Split(' ').Last();
    var handler = new JwtSecurityTokenHandler();

    try
    {
        var jwtToken = handler.ReadJwtToken(token);
        var identity = jwtToken.Principal;
        var usernameClaim = identity.FindFirst(ClaimTypes.Name);

        return usernameClaim != null ? usernameClaim.Value : null;
    }
    catch (Exception ex)
    {
        throw new Exception("Invalid or expired JWT token.", ex);
    }
}
```

