       const newResponse = {
         id: Date.now(),
         choices: {
           relevance: event.target.choices.value,
           quantity: responses[index].state
         }
       };
       setResponses([...responses, newResponse]);
       sendResponse(newResponse);
     }

     async function sendResponse(response) {
       try {
         await axios.post('http://localhost:8080/response', response);
       } catch (error) {
         console.log('Error sending response: ', error);
