**Step 2: Creating the Blockchain Class**

Create a new file called `blockchain.js`. This file will contain the logic of creating blocks and maintaining the blockchain.

```javascript
// blockchain.js
const { cryptoHash } = require('./util');

class Block {
  constructor(index, timestamp, data, previousHash = '') {
    this.index = index;
    this.timestamp = timestamp;
    this.data = data;
    this.previousHash = previousHash;
    this.hash = cryptoHash(this.index, this.previousHash, this.timestamp, JSON.stringify(this.data));
  }
}

class Blockchain {
  constructor() {
    this.chain = [this.createGenesisBlock()];
  }

  createGenesisBlock() {
    return new Block(0, Date.now(), "Genesis Block", "0");
  }

  getLatestBlock() {
    return this.chain[this.chain.length - 1];
  }

  addBlock(newBlock) {
    newBlock.previousHash = this.getLatestBlock().hash;
    newBlock.hash = cryptoHash(newBlock.index, newBlock.previousHash, newBlock.timestamp, JSON.stringify(newBlock.data));
    this.chain.push(newBlock);
  }
}

module.exports = Blockchain;
