 I'd be happy to help you create a decorator for a Nest.js middleware function that checks the `NODE_ENV` environment variable and behaves accordingly. Here's an example of how you might implement this decorator:

```typescript
import { createDecorator, ExecutionContext } from '@nestjs/common';
import { NextFunction, Request, Response } from 'express';

export const CheckNodeEnv = createDecorator({
  name: 'checkNodeEnv',
  options: {
    priority: Infinity, // Ensure this decorator is executed before other decorators
  },
})();

export function checkNodeEnvMiddleware(envToCheck: string): Function {
  return (req: Request, res: Response, next: NextFunction) => {
    if (process.env.NODE_ENV === envToCheck) {
      next();
    } else {
      res.status(403).send(false);
    }
  };
}

CheckNodeEnv.middleware = checkNodeEnvMiddleware;

export function CheckNodeEnvDecorator(envToCheck: string) {
  return CreateContextMatcherDataFunction(CheckNodeEnv, (ctx: ExecutionContext) => {
    const req = ctx.switchToHttp().getRequest();
    return { req, envToCheck };
  });
}

function CreateContextMatcherDataFunction<T>(decorator: Function, fn: Function): Function {
  return (target: Object, propertyKey: PropertyKey, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;
    descriptor.value = async function (...args: any[]) {
      const contextData = await fn(this.constructor.getPrototypeOf(), propertyKey, this);

      const result = await originalMethod.apply(this, args);
      if (!result && decorator.middleware) {
        decorator.middleware(contextData.req, contextData.res, (next) => {
          decorator.middleware(contextData.req, contextData.res, next);
        });
      }

      return result;
    };

    return descriptor;
  };
}
```

