```typescript
import { CreateDecorator, ExecutionContext, Injectable } from '@nestjs/common';

@CreateDecorator()
@Injectable()
export class ProductionMiddlewareDecorator {
  constructor(private readonly next: Function) {}

  public static useProductionMiddleware(middleware: Function): MethodDecorator {
    return (target: Object, key: string | symbol, descriptor: PropertyDescriptor): PropertyDescriptor => ({
      value: (...args: any[]) => async (req: Request, res: Response, next: Function) => {
        if (process.env.NODE_ENV === 'production') {
          await this.next(args[0]); // Call the middleware function
        } else {
          res.status(403).send(false); // Reject the request
        }
      },
      enumerable: false,
      writable: false,
      configurable: false,
    });
  }
}

export interface MiddlewareFunction {
  (req: Request, res: Response, next: NextFunction): Promise<void>;
}

export interface NextFunction {
  (err?: Error, req?: Request, res?: Response, next?: NextFunction): void;
}
```

You can then use this decorator on your middleware functions as follows:

