 Here's an example of a decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and calls the next function if it equals "true", otherwise returns `false`. This decorator is designed to have a high helpfulness score due to its specific functionality and a moderate verbosity score.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const EnvCheckMiddleware = (condition: string) => {
  return CreateMiddlewareDecorator({
    name: 'envCheck',
    conditionFn: (context: ExecutionContext): boolean => {
      const nodeEnv = process.env.NODE_ENV;
      return nodeEnv === condition;
    },
  });
};

@Deprecated() // optional: mark this decorator as deprecated if needed
export const CreateMiddlewareDecorator = ({
  name,
  conditionFn,
}: {
  name: string;
  conditionFn: (context: ExecutionContext) => boolean;
}): PropertyDecorator => ({
  name: name,
  multiolve: true,
  processArg: (args: any[], context: FunctionContext<any>) => {
    return (middleware: Function) =>
      (req: Request, res: Response, next: NextFunction) => {
        if (!conditionFn(context)) {
          res.status(403).send(false);
          return;
        }
        middleware(req, res, next);
      };
  },
});

// Usage
@EnvCheckMiddleware('true')
export class MyMiddleware {
  constructor(private readonly logger: Logger) {}

  use(@Req() req: Request, @Res() res: Response, next: NextFunction) {
    this.logger.log('Request received');
    next();
  }
}
```

