 To create a simple toast notification using React and the useContextHook, follow these steps:

First, let's create a ToastContext provider component that will hold the state for showing and hiding the toast message:

```javascript // ToastContext.js
import { createContext } from "react";

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [isToastVisible, setIsToastVisible] = React.useState(false);

  const toggleToast = () => {
    setIsToastVisible(!isToastVisible);
    setTimeout(() => setIsToastVisible(false), 3000);
  };

  return (
    <ToastContext.Provider value={{ isToastVisible, toggleToast }}>
      {children}
    </ToastContext.Provider>
  );
};
```

Now, create a Toast component that will display the toast message:

```javascript // Toast.js
import React from "react";
import { useContext } from "react";
import "./styles.css";

const Toast = () => {
  const { isToastVisible, toggleToast } = useContext(ToastContext);

  if (!isToastVisible) return null;

  return (
    <div className="toast">
      <button onClick={toggleToast}>X</button>
      <p>This is a toast notification!</p>
    </div>
  );
};

export default Toast;
```

Lastly, wrap your application with the `ToastProvider` component and display the `Toast` component:

```javascript // App.js
import React from "react";
import "./App.css";
import ToastProvider from "./components/ToastContext";
import Toast from "./components/Toast";

function App() {
  return (
    <ToastProvider>
      <div className="App">
        <button onClick={() => alert("You clicked me!")}>Click me!</button>
        <Toast />
      </div>
    </ToastProvider>
  );
}

export default App;
```

