# Set your domain and forest FQDN
$DomainFQDN = "yourdomain.com"
$ForestFQDN = "forest.yourdomain.com"

# Function to get all SIDs from AD users and groups
function Get-ADSID {
    # Create an empty array to store SIDs
    $ADSIDs = @()

    # Search for all users and groups in the domain and forest
    $Users = Get-ADObject -Filter 'objectClass -eq "user"' -SearchBase "DC=$,DC=$($DomainFQDN)" -SearchScope Subtree
    $Groups = Get-ADObject -Filter 'objectClass -eq "group"' -SearchBase "DC=$,DC=$($DomainFQDN)" -SearchScope Subtree

    # Add each user's SID to the array
    foreach ($User in $Users) {
        $ADSIDs += $User.SID
    }

    # Add each group's SID and its transitive member SIDs to the array
    foreach ($Group in $Groups) {
        $ADSIDs += $Group.SID
        $TransitiveMembers = Get-ADPrincipalGroupMembership -Identity $Group -Recursive | ForEach-Object {$_.Member}
        $TransitiveMembers | ForEach-Object { $ADSIDs += $_.$_.SID }
    }

    # Return the array of SIDs
    return $ADSIDs
}

